<?php
class Reporte_conductor_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function tiene_km(){return $this->db->field_exists('viaje_km_salida','viaje')&&$this->db->field_exists('viaje_km_llegada','viaje');}
 public function tiene_incidencias(){return $this->db->table_exists('viaje_incidencia');}
 public function listas(){return array('conductores'=>$this->db->query("SELECT conductor_id,conductor_codigo,conductor_nombres,conductor_apellidos FROM conductor ORDER BY conductor_apellidos,conductor_nombres")->result_array(),'rutas'=>$this->db->query("SELECT ruta_id,ruta_nombre FROM ruta ORDER BY ruta_nombre")->result_array());}
 private function base_where($f,&$p){$w="v.viaje_fechasalida BETWEEN ? AND ? AND vc.estado_id=1";$p=array($f['desde'],$f['hasta']);if($f['conductor_id']>0){$w.=" AND vc.conductor_id=?";$p[]=$f['conductor_id'];}if($f['ruta_id']>0){$w.=" AND v.ruta_id=?";$p[]=$f['ruta_id'];}return $w;}
 private function incidencia_join(){return $this->tiene_incidencias()?"LEFT JOIN (SELECT viaje_id,COUNT(*) incidencias FROM viaje_incidencia WHERE estado_id=1 GROUP BY viaje_id) inc ON inc.viaje_id=v.viaje_id":"";}
 private function incidencia_expr(){return $this->tiene_incidencias()?"COALESCE(inc.incidencias,0)":"0";}
 private function km_expr(){return $this->tiene_km()?"CASE WHEN v.viaje_km_llegada>=v.viaje_km_salida THEN v.viaje_km_llegada-v.viaje_km_salida ELSE 0 END":"0";}
 public function resumen($f){$p=array();$w=$this->base_where($f,$p);$sql="SELECT c.conductor_id,CONCAT_WS(' ',COALESCE(c.conductor_apellidos,''),COALESCE(c.conductor_nombres,'')) conductor,c.conductor_codigo,COUNT(DISTINCT v.viaje_id) viajes,COUNT(DISTINCT v.ruta_id) rutas,SUM(COALESCE(pax.pasajeros,0)) pasajeros,SUM(".$this->km_expr().") kilometros,SUM(".$this->incidencia_expr().") incidencias,MIN(v.viaje_fechasalida) primera_fecha,MAX(v.viaje_fechasalida) ultima_fecha FROM viaje_conductor vc INNER JOIN conductor c ON c.conductor_id=vc.conductor_id INNER JOIN viaje v ON v.viaje_id=vc.viaje_id LEFT JOIN (SELECT viaje_id,COUNT(*) pasajeros FROM pasaje WHERE estado_id=54 GROUP BY viaje_id) pax ON pax.viaje_id=v.viaje_id ".$this->incidencia_join()." WHERE $w GROUP BY c.conductor_id,c.conductor_nombres,c.conductor_apellidos,c.conductor_codigo ORDER BY viajes DESC,conductor";return $this->db->query($sql,$p)->result_array();}
 public function detalle($f){$p=array();$w=$this->base_where($f,$p);$sql="SELECT v.viaje_id,v.viaje_fechasalida fecha,v.viaje_horasalida hora,CONCAT_WS(' ',COALESCE(c.conductor_apellidos,''),COALESCE(c.conductor_nombres,'')) conductor,vc.viaje_conductor_rol rol,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta,CONCAT_WS(' - ',ve.vehiculo_placa,ve.vehiculo_marca) vehiculo,COALESCE(pax.pasajeros,0) pasajeros,".$this->km_expr()." kilometros,".$this->incidencia_expr()." incidencias,COALESCE(vc.viaje_conductor_observacion,'') observacion FROM viaje_conductor vc INNER JOIN conductor c ON c.conductor_id=vc.conductor_id INNER JOIN viaje v ON v.viaje_id=vc.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id LEFT JOIN vehiculo ve ON ve.vehiculo_id=v.vehiculo_id LEFT JOIN (SELECT viaje_id,COUNT(*) pasajeros FROM pasaje WHERE estado_id=54 GROUP BY viaje_id) pax ON pax.viaje_id=v.viaje_id ".$this->incidencia_join()." WHERE $w ORDER BY v.viaje_fechasalida DESC,v.viaje_horasalida DESC,vc.viaje_conductor_orden";return $this->db->query($sql,$p)->result_array();}
}
